package cn.zhuatech.qms.deep;import cn.zhuatech.qms.common.ApiResponse;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/quality-ops") public class DeepQualityController{private final DeepQualityService s;public DeepQualityController(DeepQualityService x){s=x;}@GetMapping("/workspace")ApiResponse<?> workspace(){return ApiResponse.ok(s.workspace());}@PostMapping("/inspections")ApiResponse<?> inspect(@RequestBody DeepQualityService.InspectionInput x){return ApiResponse.ok(s.inspect(x));}@PostMapping("/inspections/{id}/result")ApiResponse<?> result(@PathVariable Long id,@RequestBody DeepQualityService.ResultInput x){return ApiResponse.ok(s.record(id,x));}@PostMapping("/nonconformances/{id}/disposition")ApiResponse<?> disposition(@PathVariable Long id,@RequestBody DeepQualityService.DispositionInput x){return ApiResponse.ok(s.disposition(id,x));}@PostMapping("/capas")ApiResponse<?> capa(@RequestBody DeepQualityService.CapaInput x){return ApiResponse.ok(s.capa(x));}@PostMapping("/capas/{id}/submit")ApiResponse<?> submit(@PathVariable Long id,@RequestBody DeepQualityService.EvidenceInput x){return ApiResponse.ok(s.submitCapa(id,x));}}
